function EndMessageFrame({ active, progress, onSubmitSuccess }) {
  const [name, setName] = React.useState("");
  const [message, setMessage] = React.useState("");
  const [submitState, setSubmitState] = React.useState("idle");
  const messageCount = Array.from(message).length;
  const hasMessage = message.trim().length > 0;

  const handleMessageChange = (event) => {
    const nextMessage = Array.from(event.target.value).slice(0, 500).join("");
    setMessage(nextMessage);
    if (submitState !== "submitting") setSubmitState("idle");
  };

  const handleSubmit = async () => {
    if (!message.trim()) {
      return;
    }

    setSubmitState("submitting");

    try {
      const response = await fetch(GOOGLE_APPS_SCRIPT_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "text/plain;charset=UTF-8" },
        body: JSON.stringify({ name, message }),
      });

      if (!response.ok) throw new Error("Message submission failed");

      onSubmitSuccess();
    } catch {
      setSubmitState("error");
    }
  };

  return (
    <article className={`phone-frame ending-page end-message-page ${active ? "is-active" : ""}`} id="end-msg-box" style={pageBgStyle("end-msg-box")}>
      <p className="end-message-copy">獨立出版電子Zine，一腳踢完成，<br />假如你喜歡我的作品，歡迎隨緣課金，<br />讓筆者可以維持生命。</p>
      <button className="end-action end-payme" type="button"><span className="end-payme-brand">PayMe</span>{" "}贊助一抹人間煙火</button>
      <a className="end-action end-instagram" href="https://www.instagram.com/g.c.d___/" target="_blank" rel="noreferrer">Instagram</a>
      <label className="end-message-label" htmlFor="end-message">你對作狀生活俱樂部的 Re：</label>
      <input
        id="end-name"
        className="end-name-input"
        type="text"
        value={name}
        onChange={(event) => {
          setName(event.target.value);
          if (submitState !== "submitting") setSubmitState("idle");
        }}
        placeholder="你的名字/"
        aria-label="你的名字"
      />
      <div className="end-message-field">
        <textarea
          id="end-message"
          className="end-message-input"
          value={message}
          onChange={handleMessageChange}
          placeholder="有些話未必要有答案"
          maxLength={500}
          aria-label="你對作狀生活俱樂部的 Re"
        />
        {messageCount > 0 && <output className="end-message-count">{messageCount} / 500</output>}
      </div>
      <button className="end-action end-send" type="button" onClick={handleSubmit} disabled={!hasMessage || submitState === "submitting"}>
        {submitState === "submitting" ? "Sending..." : "Send"}
      </button>
      {submitState === "error" && <p className="end-submit-status is-error" role="alert">Re: 未送到，請再試一次。</p>}
      <JourneyBottomNav pageId="end-msg-box" progress={progress} />
    </article>
  );
}

function RollerFrame({ active, progress, onScrollProgress, startToken }) {
  const rollerScrollRef = React.useRef(null);
  const handledSendTokenRef = React.useRef(0);
  const [rollerPhase, setRollerPhase] = React.useState("idle");
  const [rollerReply, setRollerReply] = React.useState("再見。");

  React.useEffect(() => {
    if (!active) {
      setRollerPhase("idle");
      return undefined;
    }

    if (rollerPhase !== "idle") return undefined;

    const enteredAfterSend = startToken > handledSendTokenRef.current;
    if (enteredAfterSend) handledSendTokenRef.current = startToken;

    setRollerReply(enteredAfterSend ? "收到了。" : "再見。");
    setRollerPhase("intro");
    return undefined;
  }, [active, rollerPhase, startToken]);

  React.useEffect(() => {
    if (!active || rollerPhase !== "fading") return undefined;

    const fadeTimer = window.setTimeout(() => setRollerPhase("rolling"), 2000);
    return () => window.clearTimeout(fadeTimer);
  }, [active, rollerPhase]);

  React.useEffect(() => {
    if (!active || rollerPhase !== "rolling") return undefined;

    const scrollNode = rollerScrollRef.current;
    if (!scrollNode) return undefined;

    const duration = 20000;
    const target = Math.max(0, scrollNode.scrollHeight - scrollNode.clientHeight);
    let animationFrame;
    let startTime;

    const roll = (time) => {
      if (!startTime) startTime = time;
      const elapsed = Math.min((time - startTime) / duration, 1);
      scrollNode.scrollTop = target * elapsed;

      if (elapsed < 1) {
        animationFrame = window.requestAnimationFrame(roll);
      } else {
        setRollerPhase("complete");
      }
    };

    animationFrame = window.requestAnimationFrame(roll);
    return () => window.cancelAnimationFrame(animationFrame);
  }, [active, rollerPhase]);

  const isArtVisible = ["fading", "rolling", "complete"].includes(rollerPhase);
  const isScrollReady = rollerPhase === "complete";

  return (
    <article className={`phone-frame ending-page roller-page ${active ? "is-active" : ""}`} id="roller" style={pageBgStyle("roller")}>
      <div
        className={`ending-scroll roller-scroll ${isScrollReady ? "is-scroll-ready" : "is-scroll-locked"}`}
        ref={rollerScrollRef}
        onScroll={(event) => {
        const element = event.currentTarget;
        const distance = element.scrollHeight - element.clientHeight;
        onScrollProgress(distance > 0 ? element.scrollTop / distance : 0);
        }}
      >
        <div className="roller-canvas">
          <img className={`roller-art ${isArtVisible ? "is-visible" : ""}`} src={assetSrc("/assets/png-pages/Outro/roller.png")} alt="" />
          {isScrollReady && <span className="ending-scroll-marker" aria-hidden="true" />}
        </div>
      </div>
      <header className="roller-header" aria-label={`Re: ${rollerReply}`}>
        {rollerPhase !== "idle" && (
          <ReTypingLabel
            text={`Re: ${rollerReply}`}
            active={active && rollerPhase !== "idle"}
            onComplete={() => setRollerPhase("fading")}
          />
        )}
      </header>
      <JourneyBottomNav pageId="roller" progress={progress} />
    </article>
  );
}

